# TCP/IP Server in C

Here's a complete TCP/IP server implementation in C that listens for client connections and echoes back received messages.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <sys/types.h>

#define PORT 8080
#define BUFFER_SIZE 1024
#define BACKLOG 5

int main() {
    int server_fd, client_fd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_addr_len = sizeof(client_addr);
    char buffer[BUFFER_SIZE];
    int opt = 1;

    // 1. Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }
    printf("Socket created successfully\n");

    // 2. Set socket options (allow reuse of address)
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    // 3. Configure server address
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;  // Accept connections on any interface
    server_addr.sin_port = htons(PORT);

    // 4. Bind socket to address
    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Bind failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }
    printf("Socket bound to port %d\n", PORT);

    // 5. Listen for incoming connections
    if (listen(server_fd, BACKLOG) < 0) {
        perror("Listen failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }
    printf("Server listening on port %d...\n", PORT);

    // 6. Accept connections in a loop
    while (1) {
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_addr_len);
        if (client_fd < 0) {
            perror("Accept failed");
            continue;
        }

        printf("\nClient connected: %s:%d\n",
               inet_ntoa(client_addr.sin_addr),
               ntohs(client_addr.sin_port));

        // 7. Communicate with client
        while (1) {
            memset(buffer, 0, BUFFER_SIZE);
            ssize_t bytes_received = recv(client_fd, buffer, BUFFER_SIZE - 1, 0);

            if (bytes_received <= 0) {
                printf("Client disconnected\n");
                break;
            }

            printf("Received from client: %s", buffer);

            // Echo message back to client
            if (send(client_fd, buffer, bytes_received, 0) < 0) {
                perror("Send failed");
                break;
            }

            // Exit if client sends "exit"
            if (strncmp(buffer, "exit", 4) == 0) {
                printf("Closing connection with client\n");
                break;
            }
        }

        // 8. Close client socket
        close(client_fd);
    }

    // 9. Close server socket
    close(server_fd);
    return 0;
}
```

## How to Compile and Run

### Compile:
```bash
gcc -o server server.c
```

### Run:
```bash
./server
```

## Testing the Server

You can test the server using **telnet** or **netcat**:

```bash
# Using telnet
telnet localhost 8080

# Using netcat
nc localhost 8080
```

Type any message and press Enter — the server will echo it back.

## Code Explanation

| Step | Function | Purpose |
|------|----------|---------|
| 1 | `socket()` | Creates a TCP socket |
| 2 | `setsockopt()` | Allows quick reuse of the port |
| 3 | `sockaddr_in` | Configures IP/port |
| 4 | `bind()` | Binds socket to address/port |
| 5 | `listen()` | Marks socket as passive (listening) |
| 6 | `accept()` | Accepts incoming client connection |
| 7 | `recv()`/`send()` | Receives and sends data |
| 8 | `close()` | Closes the socket |

## Simple Client (Optional)

Here's a matching client to test your server:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>

#define PORT 8080
#define BUFFER_SIZE 1024

int main() {
    int sock;
    struct sockaddr_in server_addr;
    char buffer[BUFFER_SIZE];

    sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("Socket failed");
        exit(EXIT_FAILURE);
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(PORT);
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

    if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Connection failed");
        exit(EXIT_FAILURE);
    }

    printf("Connected to server. Type messages ('exit' to quit):\n");

    while (1) {
        printf("> ");
        fgets(buffer, BUFFER_SIZE, stdin);

        send(sock, buffer, strlen(buffer), 0);

        memset(buffer, 0, BUFFER_SIZE);
        recv(sock, buffer, BUFFER_SIZE - 1, 0);
        printf("Server: %s", buffer);

        if (strncmp(buffer, "exit", 4) == 0) break;
    }

    close(sock);
    return 0;
}
```

**Note:** This server handles one client at a time. For handling **multiple clients simultaneously**, you'd need to use `fork()`, `pthread`, or `select()`/`epoll()`. Let me know if you'd like a multi-client version!

